import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.model_selection import StratifiedKFold
from sklearn.metrics import roc_auc_score

MAX_DRIVERS = 5

def design(feats):
    # Check if any feature shows significant association with outcome
    effects = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical':
            # For clinical features, use t-test
            y0 = feats.x[feats.y==0, i]
            y1 = feats.x[feats.y==1, i]
            t_stat, p_val = stats.ttest_ind(y0, y1, equal_var=False)
        else:
            # For other features, use Welch's t-test
            y0 = feats.x[feats.y==0, i]
            y1 = feats.x[feats.y==1, i]
            t_stat, p_val = stats.ttest_ind(y0, y1, equal_var=False)

        mean_diff = np.mean(y1) - np.mean(y0)
        auc = roc_auc_score(feats.y, feats.x[:, i])

        # Only consider features with p < 0.05 and |mean_diff| > 0.1
        if p_val < 0.05 and abs(mean_diff) > 0.1:
            effects.append((fid, abs(mean_diff), abs(t_stat), auc))

    # Sort by effect size (mean difference)
    effects.sort(key=lambda x: x[1], reverse=True)

    # If no strong effects found, return empty design
    if not effects:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Check for correlation between top features
    top_features = [f[0] for f in effects[:5]]
    correlations = {}

    # Build correlation matrix for top features
    for i, fid1 in enumerate(top_features):
        for j, fid2 in enumerate(top_features):
            if i < j:
                idx1 = feats.column(fid1)
                idx2 = feats.column(fid2)
                corr = np.corrcoef(feats.x[:, idx1], feats.x[:, idx2])[0, 1]
                if abs(corr) >= 0.6:
                    correlations[(fid1, fid2)] = corr

    # Build design using top features that aren't highly correlated
    columns = []
    products = []
    loadings = {}

    # Add top features to columns (limit to 5 to avoid overfitting)
    for i, (fid, _, _, _) in enumerate(effects):
        if len(columns) >= 5:  # Limit columns to prevent overfitting
            break

        # Skip if highly correlated with existing columns
        is_correlated = False
        for col in columns:
            if (col, fid) in correlations or (fid, col) in correlations:
                is_correlated = True
                break

        if not is_correlated:
            columns.append(fid)
            loadings[fid] = effects[i][1]  # Use effect size as loading

    # Try to add interaction terms between top features (limit to 3)
    count = 0
    for i, fid1 in enumerate(columns):
        for j, fid2 in enumerate(columns):
            if i < j and count < 3:
                products.append((fid1, fid2))
                count += 1
        if count >= 3:
            break

    # Check if any mechanism exists by fitting a simple model
    if columns:
        try:
            # Simple approach: just check if top feature alone works
            top_fid = effects[0][0]
            top_idx = feats.column(top_fid)

            # Fit simple model with just top feature
            clf = LogisticRegression(random_state=42, max_iter=1000)
            clf.fit(feats.x[:, top_idx].reshape(-1, 1), feats.y)
            y_pred_proba = clf.predict_proba(feats.x[:, top_idx].reshape(-1, 1))[:, 1]
            auc = roc_auc_score(feats.y, y_pred_proba)

            # If top feature alone gives good performance, make it a driver
            if auc > 0.6:
                return Design(
                    drivers=(top_fid,),
                    columns=tuple(columns),
                    products=tuple(products),
                    loadings=loadings
                )
        except:
            pass

    # If no robust mechanism found, return empty design
    return Design(drivers=(), columns=(), products=(), loadings={})

